func on_idle_source_cut():
	if done or source_cut_frozen:
		return source_cut_reject_collector("CUT_DUPLICATE_OR_DONE")
	var observer = get_root().get_node_or_null("NativeRandomObserver")
	if observer == null or not observer.has_method("source_cut_control") or observer.failed:
		return source_cut_reject_collector("CUT_OBSERVER_FAILURE")
	var control = observer.source_cut_control()
	if control.phase != "EMITTING" or not control.dispatching or control.emit_count != 1 or control.receiver_id != str(get_instance_id()) or control.ack != null or typeof(control.script_emit_return_observed) != TYPE_BOOL or control.script_emit_return_observed or typeof(control.script_emit_return) != TYPE_NIL or typeof(control.native_emit_error_available) != TYPE_BOOL or control.native_emit_error_available or control.native_emit_error != null:
		return source_cut_reject_collector("CUT_NOT_SYNCHRONOUS_DISPATCH")
	if control.physics != Engine.get_physics_frames() or control.idle != Engine.get_idle_frames():
		return source_cut_reject_collector("CUT_DISPATCH_FRAME_MISMATCH")
	var receipt = observer.source_completion_receipt()
	if not receipt.source_window_complete or not observer.closed or not check_source_listener_order() or Engine.is_in_physics_frame() or not receipt.clock_closed or not receipt.ui_closed or result_value == null:
		return source_cut_reject_collector("CUT_COMPLETION_GUARD")
	if receipt.cleanup == null or Engine.get_physics_frames() != receipt.cleanup.physics_frame + 2:
		return source_cut_reject_collector("CUT_TWO_FUTURE_PHYSICS")
	# Atomic synchronous once guard BEFORE any sampling or callback that can reenter.
	source_cut_frozen = true
	barrier_ok = check_barrier()
	var snapshot = stable_snapshot() # Exactly one full terminal sampling; original getter chain.
	var king_final = observer.source_runtime_snapshot() # Same existing readonly SOURCE sampling.
	if done or observer.failed:
		return source_cut_reject_collector("CUT_SAMPLING_FAILURE")
	var count = snapshot.events.size()
	var native_manifest = {"schema": "native-combat-capture/1", "case_id": config.case_id, "config": config, "version": game.VERSION, "engine": Engine.get_version_info(), "main_scene": ProjectSettings.get_setting("application/run/main_scene"), "physics_fps": Engine.iterations_per_second, "time_scale": Engine.time_scale, "collector_source": "phase362-single-King-oracle-only", "clean_exit": "HOST_RECORD_SEPARATELY", "native_model_admission": false}
	var validation = {"native_capture_written": true, "capture_complete": false, "host_validation_required": true, "native_checks_pass": errors.empty() and barrier_ok and not observer.failed, "end_barrier": barrier_ok, "layout": legal_checks, "errors": errors.duplicate(), "events": count, "result": result_value, "elapsed_ms": OS.get_ticks_msec() - started, "cut": {"physics": Engine.get_physics_frames(), "idle": Engine.get_idle_frames(), "preinternal": true}, "full_snapshot_reads": 1}
	source_cut_payload = {"instances": instance_rows.duplicate(true), "phases": phases.duplicate(true), "event_references": event_references.duplicate(true), "snapshot": snapshot, "native_manifest": native_manifest, "receipt": receipt, "king_cut": {"receipt": receipt, "connection_order": source_connection_order.duplicate(true), "actual_final": king_final, "source": "SAME_IDLE_INSIDE_SINK_AFTER_WRITE_BEFORE_NODE_INTERNAL"}, "validation": validation, "success": errors.empty() and barrier_ok and not observer.failed, "count": count}
	if not source_control_record("on_idle_source_cut", "FROZEN_BEFORE_ACK"):
		return source_cut_reject_collector("CUT_FROZEN_DIAGNOSTIC_FAILED")
	if not observer.ack_source_idle_cut(get_instance_id(), Engine.get_physics_frames(), Engine.get_idle_frames()):
		return source_cut_reject_collector("CUT_ACK_REJECTED")
	return true

func finish_source_cut():
	var observer = get_root().get_node_or_null("NativeRandomObserver")
	if done or source_cut_finish_entered or not source_cut_frozen or source_cut_payload == null or observer == null or not observer.has_method("source_cut_control"):
		return source_cut_reject_collector("CUT_FINALIZER_ENTRY")
	var control = observer.source_cut_control() # Observation-control primitives only, no business getter.
	if control.phase != "FINALIZING" or control.dispatching or control.emit_count != 1 or typeof(control.script_emit_return_observed) != TYPE_BOOL or not control.script_emit_return_observed or typeof(control.script_emit_return) != TYPE_NIL or typeof(control.native_emit_error_available) != TYPE_BOOL or control.native_emit_error_available or control.native_emit_error != null or control.ack == null or control.receiver_id != str(get_instance_id()) or control.physics != source_cut_payload.validation.cut.physics or control.idle != source_cut_payload.validation.cut.idle or Engine.get_physics_frames() != control.physics or Engine.get_idle_frames() != control.idle or control.failed:
		return source_cut_reject_collector("CUT_FINALIZER_CONTEXT")
	source_cut_finish_entered = true
	# Serialization only below: frozen primitive DTOs, no getters/snapshots/getStats/advance.
	var jobs = [["instances.json", source_cut_payload.instances], ["phases.json", source_cut_payload.phases], ["event_references.json", source_cut_payload.event_references], ["histories.json", source_cut_payload.snapshot.histories], ["final_state.json", source_cut_payload.snapshot.state], ["native_manifest.json", source_cut_payload.native_manifest], ["observer7-status.json", source_cut_payload.receipt], ["king-collector-cut.json", source_cut_payload.king_cut]]
	for job in jobs:
		write_json(job[0], job[1])
		if done:
			source_control_record("finish_source_cut", "FROZEN_WRITE_FAILED", {"file": job[0]})
			return false # Existing writer already preserved primary and requested exit2.
	write_jsonl("events.jsonl", source_cut_payload.snapshot.events)
	if done:
		source_control_record("finish_source_cut", "FROZEN_WRITE_FAILED", {"file": "events.jsonl"})
		return false
	write_json("validation.json", source_cut_payload.validation)
	if done:
		source_control_record("finish_source_cut", "FROZEN_WRITE_FAILED", {"file": "validation.json"})
		return false
	if not source_control_record("finish_source_cut", "SERIALIZED_BEFORE_RETURN", {"events": source_cut_payload.count}):
		return source_cut_reject_collector("CUT_FINALIZER_DIAGNOSTIC_FAILED")
	done = true
	print("NATIVE_CAPTURE_WRITTEN " + JSON.print({"success": source_cut_payload.success, "events": source_cut_payload.count, "path": ProjectSettings.globalize_path(OUT)}))
	event_objects.clear()
	quit(0 if source_cut_payload.success else 2)
	return source_cut_payload.success

func combatEndDeferred():
	NativeRandomObserver.entry("Core/Game.gd::combatEndDeferred", self, {})
	emit_signal("combat_end", roundResults[curRound - 1])

	EventBus.disconnectAll()
	PLAYER.combatEnd()
	OPPONENT.combatEnd()
	combatTimer.combatEnd()

	if roundResults[curRound - 1] == RoundResult.Win:
		OPPONENT.setCurrentHealth(0)
		PLAYER.setCurrentHealth(max(1, PLAYER.getCurrentHealth()))
	else:
		PLAYER.setCurrentHealth(0)
		OPPONENT.setCurrentHealth(max(1, OPPONENT.getCurrentHealth()))

	for item in PLAYER.INVENTORY.getItems() + OPPONENT.INVENTORY.getItems():
		item.combatEnd()

	ropeSpeedups.clear()
	cubeAdvanced.clear()
	sandbagActive = false

	curRound += 1
	if curMode != Mode.History:
		emit_signal("round_result")


	if SteamHelper.canUnlock():
		if getLastRoundResult() == RoundResult.Win:
			if combatTimer.combatTime < 3:
				SteamHelper.unlockAchievement("FastBattle")
			elif combatTimer.combatTime >= 45:
				SteamHelper.unlockAchievement("SlowBattle")

			var noWeapon = true
			for item in PLAYER.INVENTORY.getItems():
				if item.hasType(Item.Type.Weapon):
					noWeapon = false
					break
			if noWeapon:
				SteamHelper.unlockAchievement("NoWeapon")

			if PLAYER.getRelativeHealth() == 1:
				SteamHelper.unlockAchievement("FullHealth")
			elif PLAYER.getCurrentHealth() == 1:
				SteamHelper.unlockAchievement("1Health")

			checkForInventoryAchievements()

		if PLAYER.getBuffStacks() >= 100:
			SteamHelper.unlockAchievement("ManyBuffs")
		elif OPPONENT.getDebuffStacks() >= 100:
			SteamHelper.unlockAchievement("ManyDebuffs")

		if numTimesOutOfStamina >= 10:
			SteamHelper.unlockAchievement("OutOfStamina")



	Sound.fadeOutBGM(1)

	if runOver():
		if curMode == Mode.Lobbies:
			endRun_lobby()
		else:
			endRun(true, true)
	NativeRandomObserver.leave("Core/Game.gd::combatEndDeferred", self, null, "return_implicit")

static const int max_physics_steps = 8;
if (fixed_fps == -1 && advance.physics_steps > max_physics_steps) {
	step -= (advance.physics_steps - max_physics_steps) * frame_slice;
	advance.physics_steps = max_physics_steps;
}

bool exit = false;

for (int iters = 0; iters < advance.physics_steps; ++iters) {
	if (InputDefault::get_singleton()->is_using_input_buffering() && agile_input_event_flushing) {
		InputDefault::get_singleton()->flush_buffered_events();
	}

	Engine::get_singleton()->_in_physics = true;
	Engine::get_singleton()->_physics_frames++;

	uint64_t physics_begin = OS::get_singleton()->get_ticks_usec();

	// Prepare the fixed timestep interpolated nodes
	// BEFORE they are updated by the physics,
	// otherwise the current and previous transforms
	// may be the same, and no interpolation takes place.
	OS::get_singleton()->get_main_loop()->iteration_prepare();

	PhysicsServer::get_singleton()->flush_queries();

	Physics2DServer::get_singleton()->sync();
	Physics2DServer::get_singleton()->flush_queries();

	if (OS::get_singleton()->get_main_loop()->iteration(frame_slice * time_scale)) {
		exit = true;
		Engine::get_singleton()->_in_physics = false;
		break;
	}

	NavigationServer::get_singleton_mut()->process(frame_slice * time_scale);
	message_queue->flush();

	PhysicsServer::get_singleton()->step(frame_slice * time_scale);

	Physics2DServer::get_singleton()->end_sync();
	Physics2DServer::get_singleton()->step(frame_slice * time_scale);

	message_queue->flush();

	OS::get_singleton()->get_main_loop()->iteration_end();

	physics_process_ticks = MAX(physics_process_ticks, OS::get_singleton()->get_ticks_usec() - physics_begin); // keep the largest one for reference
	physics_process_max = MAX(OS::get_singleton()->get_ticks_usec() - physics_begin, physics_process_max);

	Engine::get_singleton()->_in_physics = false;
}

if (InputDefault::get_singleton()->is_using_input_buffering() && agile_input_event_flushing) {
	InputDefault::get_singleton()->flush_buffered_events();
}

uint64_t idle_begin = OS::get_singleton()->get_ticks_usec();

if (OS::get_singleton()->get_main_loop()->idle(step * time_scale)) {
	exit = true;
}

bool SceneTree::iteration(float p_time) {
	root_lock++;

	current_frame++;

	flush_transform_notifications();

	if (MainLoop::iteration(p_time)) {
		_quit = true;
	}
	physics_process_time = p_time;

	emit_signal("physics_frame");

	_notify_group_pause("physics_process_internal", Node::NOTIFICATION_INTERNAL_PHYSICS_PROCESS);
	if (GLOBAL_GET("physics/common/enable_pause_aware_picking")) {
		call_group_flags(GROUP_CALL_REALTIME, "_viewports", "_process_picking", true);
	}
	_notify_group_pause("physics_process", Node::NOTIFICATION_PHYSICS_PROCESS);
	_flush_ugc();
	MessageQueue::get_singleton()->flush(); //small little hack

	process_tweens(p_time, true);

	flush_transform_notifications();
	call_group_flags(GROUP_CALL_REALTIME, "_viewports", "update_worlds");
	root_lock--;

//print_line("node count: "+itos(get_node_count()));
//print_line("TEXTURE RAM: "+itos(VS::get_singleton()->get_render_info(VS::INFO_TEXTURE_MEM_USED)));

root_lock++;

if (MainLoop::idle(p_time)) {
	_quit = true;
}

idle_process_time = p_time;

if (multiplayer_poll) {
	multiplayer->poll();
}

emit_signal("idle_frame");

MessageQueue::get_singleton()->flush(); //small little hack

flush_transform_notifications();

def validate_terminal_evidence(endpoint, clock, cleanup):
    """Expected-only finite-cut proof. Never a model termination input."""
    exact(endpoint, ('schema', 'phase', 'physics_frame', 'idle_frame', 'passes', 'two_future_physics_signals', 'fx_exact_comparison'))
    if endpoint['schema'] != 'phase111-fixed-endpoint/1' or endpoint['phase'] != 'idle_pre_internal_flush' or type(endpoint['two_future_physics_signals']) is not int or endpoint['two_future_physics_signals'] != 2 or endpoint['fx_exact_comparison'] != 'NOT_EVALUATED_REQUIRES_MODEL':
        raise ValueError('finite terminal source-cut schema')
    for name in ('physics_frame', 'idle_frame', 'passes'):
        _counter(endpoint[name])
    final = clock.passes[-1]
    if final.kind != 'idle' or (endpoint['physics_frame'], endpoint['idle_frame'], endpoint['passes']) != (final.physics_frame, final.idle_frame, len(clock.passes)):
        raise ValueError('terminal last actual idle cut/trailing')
    exact(cleanup, ('physics_frame', 'idle_frame', 'is_in_physics_frame'))
    _counter(cleanup['physics_frame']); _counter(cleanup['idle_frame'])
    if type(cleanup['is_in_physics_frame']) is not bool:
        raise ValueError('actual cleanup phase BOOL')
    kind = 'physics' if cleanup['is_in_physics_frame'] else 'idle'
    positions = [i for i, p in enumerate(clock.passes) if (p.kind, p.physics_frame, p.idle_frame) == (kind, cleanup['physics_frame'], cleanup['idle_frame'])]
    if len(positions) == 1:
        tail = clock.passes[positions[0] + 1:]
    elif not positions and kind == 'idle' and (cleanup['physics_frame'], cleanup['idle_frame']) == (clock.physics_frame, clock.idle_frame):
        tail = clock.passes
    else:
        raise ValueError('cleanup actual clock association')
    if sum(p.kind == 'physics' for p in tail) != 2:
        raise ValueError('exactly two future physics signals')
    second = max(i for i, p in enumerate(tail) if p.kind == 'physics')
    if len(tail) != second + 2 or tail[-1].kind != 'idle':
        raise ValueError('first eligible idle-preinternal only; EOF/trailing rejected')
    return dict(status='EXPECTED_ONLY_TWO_FUTURE_PHYSICS_IDLE_PREINTERNAL', no_model_stop_command=True)
